            }
          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Bandwidth saturation and elephant flows",
          "layoutId": "layout_1"
        }
      ]
    }
  },
  "expressions": {},
  "applicationProperties": {
    "hideEdit": false,
    "hideExport": false
  }
}
